import os


class Config:
    """
    Configuration for the Essay Scoring project.
    Implements settings for the 'Sparse N-gram Linear Regression' approach.
    """

    # --- Reproducibility ---
    SEED = 42

    # --- Paths ---
    # Input Metadata (Generated by the provided script)
    METADATA_DIR = "./metadata"
    TRAIN_DATA_PATH = os.path.join(METADATA_DIR, "train.csv")
    VAL_DATA_PATH = os.path.join(METADATA_DIR, "val.csv")
    TEST_DATA_PATH = os.path.join(METADATA_DIR, "test.csv")

    # Output Directories
    WORKING_DIR = "./working/idea_1"
    CACHE_DIR = os.path.join(WORKING_DIR, "cache")
    SUBMISSION_DIR = "./submission"

    # Artifact Paths
    # We save the trained model to reuse during inference
    # Note: Vectorizer is now handled by the HuggingFace tokenizer
    MODEL_PATH = os.path.join(WORKING_DIR, "model.pth")
    SUBMISSION_FILE = os.path.join(SUBMISSION_DIR, "submission.csv")

    # --- Data Schema ---
    ID_COL = "essay_id"
    TEXT_COL = "full_text"
    TARGET_COL = "score"

    # --- Model Hyperparameters ---

    # Transformer Settings (Cite Lesson 00009)
    MODEL_NAME = "microsoft/deberta-v3-base"
    MAX_LENGTH = 512
    TRAIN_BATCH_SIZE = 8
    VALID_BATCH_SIZE = 16
    EPOCHS = 3
    LEARNING_RATE = 2e-5  # Uniform LR (Cite Lesson 00010)
    GRADIENT_ACCUMULATION_STEPS = 1
    MAX_GRAD_NORM = 1000
    NUM_WORKERS = 2

    # Device
    import torch

    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    # --- Post-processing ---
    # Constraints for the target variable
    SCORE_MIN = 1
    SCORE_MAX = 6

    @classmethod
    def create_dirs(cls):
        """Creates necessary output directories if they do not exist."""
        os.makedirs(cls.WORKING_DIR, exist_ok=True)
        os.makedirs(cls.CACHE_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)
